c048.try_sql:
-- DDL (here COMMENT) commits the open transaction: the row survives ROLLBACK
CREATE TABLE lab_c048_t (n NUMBER);
INSERT INTO lab_c048_t VALUES (1);
COMMENT ON TABLE lab_c048_t IS 'DDL robi COMMIT';
ROLLBACK;
SELECT n FROM lab_c048_t;

c049.try_sql:
-- DELETE is DML: ROLLBACK brings the rows back (TRUNCATE would not allow that)
DELETE FROM order_items;
SELECT COUNT(*) FROM order_items;
ROLLBACK;
SELECT COUNT(*) FROM order_items;

c050.try_sql:
-- Both WHENs are true: ALL inserts 2 rows, FIRST only 1
INSERT ALL
  WHEN x > 0 THEN INTO promotions VALUES (x, 'ALL-1', 5)
  WHEN x > 0 THEN INTO promotions VALUES (x + 10, 'ALL-2', 5)
SELECT 1 AS x FROM dual;
INSERT FIRST
  WHEN x > 0 THEN INTO promotions VALUES (x, 'FIRST-1', 5)
  WHEN x > 0 THEN INTO promotions VALUES (x + 10, 'FIRST-2', 5)
SELECT 2 AS x FROM dual;
SELECT * FROM promotions ORDER BY promo_id;

c052.try_sql:
-- The change before the savepoint stays, the change after it disappears
UPDATE employees SET salary = 25000 WHERE employee_id = 100;
SAVEPOINT s1;
UPDATE employees SET salary = 1 WHERE employee_id = 100;
ROLLBACK TO s1;
SELECT salary FROM employees WHERE employee_id = 100;

