c503.try_sql:
-- Only order 1001 is matched. After /20 both its lines have a price < 100 and disappear;
-- lines 1004/1 and 1006/2 (price < 100) stay, because they were not matched
MERGE INTO order_items t
USING (SELECT 1001 AS oid FROM dual) s
ON (t.order_id = s.oid)
WHEN MATCHED THEN UPDATE SET t.unit_price = t.unit_price / 20
  DELETE WHERE t.unit_price < 100;
SELECT order_id, line_no, unit_price FROM order_items WHERE unit_price < 100 OR order_id = 1001;

c504.try_sql:
-- The child points to the parent: TRUNCATE raises ORA-02266, and CASCADE without ON DELETE CASCADE ORA-14705
CREATE TABLE lab_c504_p (id NUMBER CONSTRAINT lab_c504_p_pk PRIMARY KEY);
CREATE TABLE lab_c504_c (pid NUMBER CONSTRAINT lab_c504_c_fk REFERENCES lab_c504_p);
INSERT INTO lab_c504_p VALUES (1);
INSERT INTO lab_c504_c VALUES (1);
TRUNCATE TABLE lab_c504_p;
TRUNCATE TABLE lab_c504_p CASCADE;
SELECT (SELECT COUNT(*) FROM lab_c504_p) AS rodzic, (SELECT COUNT(*) FROM lab_c504_c) AS dziecko FROM dual;

c1501.try_sql:
