INSERT ALL
  INTO promotions VALUES (1, 'Wiosna', 10)
  INTO promotions VALUES (2, 'Lato', 15)
SELECT * FROM dual;
INSERT INTO promotions
SELECT 3, 'Jesień', 20 FROM dual UNION ALL SELECT 4, 'Zima', 25 FROM dual;
