c1502.try_sql:
-- The second INTO breaks the primary key: not even the first row remains (COUNT = 0)
INSERT ALL
  INTO promotions VALUES (1, 'A', 5)
  INTO promotions VALUES (1, 'B', 5)
SELECT * FROM dual;
SELECT COUNT(*) FROM promotions;

c1508.try_sql:
-- s stays after ROLLBACK TO, so a second ROLLBACK TO s works too: the salary goes back to 24000
SAVEPOINT s;
UPDATE employees SET salary = 1 WHERE employee_id = 100;
ROLLBACK TO s;
UPDATE employees SET salary = 2 WHERE employee_id = 100;
ROLLBACK TO s;
SELECT salary FROM employees WHERE employee_id = 100;

c1511.try_sql:
-- ORA-00955 (an execution error) commits row 1; a syntax error does not, so ROLLBACK undoes row 2
CREATE TABLE lab_c1511_t (n NUMBER);
INSERT INTO lab_c1511_t VALUES (1);
CREATE TABLE lab_c1511_t (n NUMBER);
INSERT INTO lab_c1511_t VALUES (2);
CREATE TABLE lab_c1511_x (n NUMBER,);
